function sortingPressProofStrip(readings) {
  const a=readings; let out=[];
  function sort(xs){if(xs.length<2)return xs;const m=Math.floor(xs.length/2),left=sort(xs.slice(0,m)),right=sort(xs.slice(m)),merged=[];let i=0,j=0;while(i<left.length||j<right.length)merged.push(j===right.length||(i<left.length&&left[i]<=right[j])?left[i++]:right[j++]);return merged;}out=sort([...a]);
  return out;
}

